mapper.sql:
WHERE o.oppt_stts_cd=#{status}
    AND o.bsn_stg_cd=#{stage}
    AND o.cust_ptnr_id=#{customer}
    AND o.bsn_part_id=#{part}
    AND to_char(to_date(o.expc_bgn_ym,'YYYY-MM')+(o.expc_mnth_qty-1)*interval '1 month','YYYY-MM') >= #{from}
    AND o.expc_bgn_ym <= #{to}
    AND (strpos(lower(o.oppt_nm),lower(#{q}))>0 OR EXISTS(SELECT 1 FROM mst.ptnr c WHERE c.ptnr_id=o.cust_ptnr_id AND strpos(lower(c.ptnr_nm),lower(#{q}))>0))
